const TaleManager = require ('../../../TaleManager');

module.exports = function getComponent (
  componentIdentifier,
  componentFlavours
) {
  const flavour = !!componentFlavours
    ? componentFlavours[componentIdentifier]
    : componentIdentifier;
  const taleIdentifier = !!flavour ? flavour : componentIdentifier;
  const componentTale = TaleManager.getTale (taleIdentifier);
  const {taleOriginName, taleName} = componentTale;
  let Component = componentTale.Component;

  if (!Component) {
    Component = TaleManager.getTale (taleOriginName);
  }
  return Component;
};
